import numpy as np
import pandas as pd
from datetime import timedelta


def _record(name, func):
    try:
        probe(name, func())
    except Exception as e:
        probe_exception(name, e)


# 1) to_timedelta([np.timedelta64("NaT", nat_unit)]) for nat_unit in s/ms/us/ns/D
for nat_unit in ["s", "ms", "us", "ns", "D"]:
    _name = f'to_timedelta([np.timedelta64("NaT", nat_unit)]) for nat_unit in s/ms/us/ns/D'
    def _f():
        return pd.to_timedelta([np.timedelta64("NaT", nat_unit)])
    _record(_name, _f)


# 2) test_to_timedelta_string_after_finer_element parametrized over first ... and one_day ...
# Record exactly under the DESCRIPTION'S OWN TEXT as the record name.
_name2 = 'test_to_timedelta_string_after_finer_element parametrized over first in [pd.Timedelta(1,"ns"), np.timedelta64(1,"ns"), timedelta(microseconds=1)] and one_day in ["1 days", "P1D"]'

_first_values = [pd.Timedelta(1, "ns"), np.timedelta64(1, "ns"), timedelta(microseconds=1)]
_one_day_values = ["1 days", "P1D"]

for first in _first_values:
    for one_day in _one_day_values:
        def _f():
            # mimic "string after finer element" behavior: add the duration string to the base
            return pd.to_timedelta([first]) + pd.to_timedelta([one_day])
        try:
            probe(_name2, _f())
        except Exception as e:
            probe_exception(_name2, e)

